require_once __DIR__.'/../config/fungsi.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$nama=trim($_POST['nama_periode']);$mulai=str_replace('T',' ',$_POST['tanggal_mulai']);$selesai=str_replace('T',' ',$_POST['tanggal_selesai']);$status=$_POST['status']==='Aktif'?'Aktif':'Nonaktif';
 if(strtotime($selesai)<=strtotime($mulai)){flash('Tanggal selesai harus setelah tanggal mulai.','danger');}else{$pdo->beginTransaction();if($status==='Aktif')$pdo->exec("UPDATE periode_voting SET status='Nonaktif'");$q=$pdo->prepare('INSERT INTO periode_voting(nama_periode,tanggal_mulai,tanggal_selesai,status) VALUES(?,?,?,?)');$q->execute([$nama,$mulai,$selesai,$status]);$pdo->commit();flash('Periode voting disimpan.');redirect('admin/periode.php');}}
$rows=$pdo->query('SELECT * FROM periode_voting ORDER BY id DESC')->fetchAll();$page_title='Periode Voting';require __DIR__.'/_layout_top.php';?>
<h1 class="section-title mb-4">Pengaturan Periode Voting</h1><div class="panel mb-4"><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><div class="row g-3"><div class="col-md-4"><label class="form-label">Nama periode</label><input class="form-control" name="nama_periode" required></div><div class="col-md-3"><label class="form-label">Mulai</label><input class="form-control" type="datetime-local" name="tanggal_mulai" required></div><div class="col-md-3"><label class="form-label">Selesai</label><input class="form-control" type="datetime-local" name="tanggal_selesai" required></div><div class="col-md-2"><label class="form-label">Status</label><select class="form-select" name="status"><option>Nonaktif</option><option>Aktif</option></select></div></div><button class="btn btn-gold mt-3">Simpan Periode</button></form></div><div class="panel table-responsive"><table class="table"><thead><tr><th>Nama</th><th>Mulai</th><th>Selesai</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $p): ?><tr><td><?= e($p['nama_periode']) ?></td><td><?= e($p['tanggal_mulai']) ?></td><td><?= e($p['tanggal_selesai']) ?></td><td><?= e($p['status']) ?></td></tr><?php endforeach; ?></tbody></table></div>
